package com.nakuul.fieldkeep;

import android.graphics.Typeface;
import android.os.Bundle;
import android.text.method.LinkMovementMethod;
import android.view.Gravity;
import android.view.ViewGroup;
import android.widget.FrameLayout;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

import androidx.activity.ComponentActivity;

public class InfoActivity extends ComponentActivity {
    @Override protected void onCreate(Bundle b){
        super.onCreate(b);Ui.prepareWindow(this,true);
        String page=getIntent().getStringExtra("page");boolean privacy="privacy".equals(page);
        FrameLayout frame=new FrameLayout(this);frame.setBackgroundColor(Ui.BG);Ui.applySystemBarInsets(frame,4,10);
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(Ui.dp(this,18),Ui.dp(this,4),Ui.dp(this,18),Ui.dp(this,4));
        TextView back=Ui.iconButton(this,"←");back.setTextSize(30);top.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,58)));back.setOnClickListener(v->finish());
        TextView title=new TextView(this);title.setText(privacy?"Privacy Policy":"About Webnix Studio");title.setTextColor(Ui.INK);title.setTextSize(23);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setGravity(Gravity.CENTER_VERTICAL);top.addView(title,new LinearLayout.LayoutParams(0,Ui.dp(this,58),1));root.addView(top);
        ScrollView scroll=new ScrollView(this);TextView text=new TextView(this);text.setText(privacy?privacyText():aboutText());text.setTextColor(Ui.INK);text.setTextSize(15);text.setLineSpacing(Ui.dp(this,3),1.08f);text.setPadding(Ui.dp(this,22),Ui.dp(this,12),Ui.dp(this,22),Ui.dp(this,42));text.setAutoLinkMask(android.text.util.Linkify.EMAIL_ADDRESSES|android.text.util.Linkify.WEB_URLS);text.setMovementMethod(LinkMovementMethod.getInstance());scroll.addView(text);root.addView(scroll,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));frame.addView(root,new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT));setContentView(frame);
    }

    private String aboutText(){return "About Webnix Studio\n\nWebnix Studio created Waymark Field Notes to make fieldwork easier to capture, organize, and document.\n\nWaymark brings site records, GPS locations, photos, voice notes, drawings, checklists, and text notes into one organized workspace. From recording observations during a site visit to preparing a field report, it helps keep important details connected to the right project.\n\nOur goal is simple: build practical tools that help people spend less time managing information and more time getting work done.\n\nWaymark Field Notes — Designed and developed by Webnix Studio.";}

    private String privacyText(){return "PRIVACY POLICY — WAYMARK FIELD NOTES\n\nEffective Date: 1 October 2026\nLast Updated: 1 October 2026\nDeveloper: Webnix Studio\nContact: waymarknote@gmail.com\n\nWebnix Studio (“we,” “us,” or “our”) develops Waymark Field Notes. This Privacy Policy explains how information is handled when you use the app, its mapping features, and our support contact.\n\n1. Local Storage and Your Information\n\nWaymark Field Notes stores your notes, site records, and attachments locally on your device. We do not operate a server that receives or stores these records.\n\nThe app does not require an account or login and does not provide cloud synchronization, cloud backup, or a backup restoration service. Webnix Studio does not maintain backup copies of your locally stored records.\n\nGoogle Maps and information you voluntarily send to our support email are handled separately, as explained below.\n\n2. Information Used Within the App\n\nDepending on the features you use, the app may process and store:\n\n• Text notes, checklists, drawings, labels, and reminders.\n• Site names, subjects, descriptions, addresses, and observations.\n• Representative names and phone numbers you enter.\n• GPS coordinates, location accuracy, and related dates and times.\n• Photos, videos, voice recordings, and files you capture or select.\n• Reports created from your records.\n\nThis information is used to provide the app’s note-taking, site documentation, organization, location, reminder, and reporting features.\n\nEntering a representative’s name or phone number into a record does not create an account with Webnix Studio.\n\n3. Device Permissions\n\nDepending on your device and the features you choose, Waymark may request permission to access:\n\n• Location: To identify locations and associate coordinates with site records.\n• Camera: To capture photos and videos.\n• Microphone: To record voice notes or audio accompanying videos.\n• Photos, media, and files: To attach selected files and save or export content.\n• Notifications: To display reminders.\n\nYou can manage or revoke permissions through your device settings. Denying or revoking a permission may limit the related feature.\n\n4. Location Information and Google Maps\n\nLocation information is used for the app’s mapping and site-record features. Coordinates saved in your records remain on your device unless you choose to export or share them. Webnix Studio does not receive your location through its own server.\n\nWaymark uses Google Maps to provide mapping functionality. These features may communicate with Google and are subject to Google’s data practices.\n\nDepending on the Google Maps component and features used, Google may process information such as your IP address, device and software details, service identifiers, map interactions, and diagnostic information. Requests to display maps or look up locations may also communicate information about the requested location.\n\nGoogle’s processing is separate from Webnix Studio’s local storage of your notes. Google determines how information it receives is handled and retained under its policies.\n\nGoogle Privacy Policy: https://policies.google.com/privacy\n\n5. Sharing and Exporting Records\n\nYou decide when to export or share your notes, reports, or attachments and which recipient or application receives them.\n\nShared content may include precise locations, addresses, names, phone numbers, photos, recordings, and other information included in the record. Review the content before sharing it, especially when it contains another person’s information.\n\nOnce you share information, the recipient or receiving service may retain or use its own copy. Deleting the original record from Waymark does not remove copies already shared or exported.\n\nWebnix Studio does not sell or rent your locally stored records or use them for advertising.\n\n6. Analytics and Crash Reporting\n\nWaymark does not use Firebase, and Webnix Studio does not receive automatic app analytics or crash reports through a separate reporting service.\n\nYou may voluntarily report an issue by emailing us. Google Maps may process its own service diagnostics as described in Section 4.\n\n7. Retention, Deletion, and Recovery\n\nYour app records remain locally on your device until you remove them. Use the app’s deletion controls to remove records. An item that remains available in a Deleted folder is still stored locally until permanently removed.\n\nYou can also use your device’s app-storage controls to clear Waymark’s app data. Files exported to other folders, original media stored elsewhere, and copies shared with other applications may need to be deleted separately.\n\nWebnix Studio cannot remotely access, delete, or restore your locally stored records. Once records are permanently deleted, we cannot recover them because we do not maintain backups.\n\nThe app does not provide a backup service. Copies or backups you create independently using your device or another service are governed by that service’s settings and policies.\n\n8. Security\n\nKeeping records on your device limits their exposure to developer-operated servers. Their protection also depends on your device’s security, operating system, permissions, and access settings.\n\nProtect your device with an appropriate screen lock, keep its software updated, and take care when granting access to your device or sharing exported files.\n\nLocal storage does not guarantee protection against every form of unauthorized access, device loss, or malicious software. No storage method is completely secure.\n\n9. Contacting Us and Privacy Requests\n\nIf you email waymarknote@gmail.com, we receive your email address, your message, and any attachments you choose to provide. This correspondence is handled through our email service, Gmail, and is separate from the records stored inside Waymark.\n\nWe use support correspondence to respond to questions, investigate issues you report, and handle privacy requests. We retain it for as long as reasonably necessary for those purposes or to meet applicable legal obligations.\n\nYou may contact us to request access, correction, or deletion of personal information held in our support correspondence, subject to applicable law. Requests concerning records stored only on your device must be carried out using the app or your device’s controls because we do not possess those records.\n\n10. Children’s Privacy\n\nWaymark does not require users to provide their age or create an account with Webnix Studio. Parents and guardians should supervise children’s use of location, recording, and sharing features.\n\nIf you believe a child’s personal information has been sent to our support email, contact us so we can review the matter and address any necessary deletion or other action.\n\n11. Changes to This Policy\n\nWe may update this Privacy Policy when the app’s features or information-handling practices change. Updates will be reflected in the “Last Updated” date. Where required, we will provide additional notice or obtain consent before introducing new processing.\n\n12. Contact Information\n\nWebnix Studio\nDeveloper of Waymark Field Notes\nEmail: waymarknote@gmail.com";}
}
